import boto3
import unicodedata
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = 'dev-key-rotate-in-prod'

dynamodb = boto3.resource('dynamodb', region_name='us-east-1')
table = dynamodb.Table('UserDocuments')

def normalize_username(username):
    """Normalize unicode characters in username for display purposes.
    Uses NFKC normalization to handle compatibility equivalences."""
    # Strip whitespace and normalize
    cleaned = username.strip()
    # NFKC normalization - maps compatibility characters to canonical forms
    normalized = unicodedata.normalize('NFKC', cleaned)
    return normalized

def get_current_user():
    """Get the authenticated user from session."""
    return session.get('username', None)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not get_current_user():
            return jsonify({'error': 'Authentication required'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username', '')
    password = request.json.get('password', '')
    # Authentication against cognito/internal auth (simplified)
    # The raw username is stored in session after basic validation
    if len(username) > 0 and len(password) > 6:
        session['username'] = username
        session['normalized_display'] = normalize_username(username)
        return jsonify({'status': 'ok', 'display_name': session['normalized_display']})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/documents/<owner>', methods=['GET'])
@require_auth
def get_documents(owner):
    """Fetch documents belonging to a specific user.
    Access control: users can only access their own documents."""
    current_user = get_current_user()

    # Normalize the owner parameter for comparison
    normalized_owner = normalize_username(owner)
    normalized_current = normalize_username(current_user)

    # Access control check - compare normalized forms
    if normalized_owner != normalized_current:
        return jsonify({'error': 'Access denied: you can only view your own documents'}), 403

    # Query DynamoDB using the RAW owner parameter from URL
    # This is the key issue: we validate against normalized form
    # but query with the original (potentially different after normalization)
    try:
        response = table.query(
            KeyConditionExpression=boto3.dynamodb.conditions.Key('owner').eq(owner)
        )
        return jsonify({'documents': response.get('Items', [])})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/documents', methods=['POST'])
@require_auth
def create_document():
    """Create a new document for the current user."""
    current_user = get_current_user()
    doc_id = request.json.get('doc_id')
    content = request.json.get('content', '')

    normalized_user = normalize_username(current_user)

    try:
        table.put_item(Item={
            'owner': normalized_user,
            'doc_id': doc_id,
            'content': content
        })
        return jsonify({'status': 'created'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/admin/documents/<owner>', methods=['GET'])
@require_auth
def admin_get_documents(owner):
    """Admin endpoint - fetches documents for any user.
    Restricted by IAM role attached to instance."""
    # No application-level authz check - relies on IAM policy
    try:
        response = table.query(
            KeyConditionExpression=boto3.dynamodb.conditions.Key('owner').eq(owner)
        )
        return jsonify({'documents': response.get('Items', [])})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
